  'Units_Guide_Sub' => 'ንዑስ አሃድ፦ «መሰረታዊ አሃድ» ይምረጡ፣ ከዚያ ወደዚያ መሰረታዊ አሃድ ለመቀየር «ኦፕሬተር» እና «የስራ እሴት» ይጠቀሙ።',
  'Units_Guide_Example_Multiply' => 'ምሳሌ፦ ሳጥን መሰረታዊ አሃዱ ቁራጭ፣ ኦፕሬተር * እና እሴት 12። 1 ሳጥን መሸጥ ከክምችት 12 ቁራጭ ያወጣል።',
