  'Units_Guide_Note' => 'እንደ «መሰረታዊ አሃድ» ሊመረጡ የሚችሉት መሰረታዊ አሃዶች ብቻ ናቸው፤ ንዑስ አሃዶች እስከሚጠቀሙበት ድረስ አሃድ ሊሰረዝ አይችልም።',
