  'Show_Items_Tax_Desc' => 'የእያንዳንዱ ምርት የራሱ ታክስ ድምር፣ እንደ «ጠቅላላ የእቃዎች ታክስ» መስመር ይታተማል። ሲነቃ ንዑስ ድምሩ እነዚህን ታክሶች ሳያካትት ይታያል።',
  'Show_Discount_Desc' => 'በሙሉ ሽያጩ ላይ የሚተገበረው ቅናሽ (ማንኛውንም የነጥብ ቅናሽ ጨምሮ)፣ በድምሮች ውስጥ እንደ የራሱ መስመር ይታተማል።',
